let settingsDraft=false,appliedRevision=-1,workspaceLoaded=false;
const busyOperations=new Set();
const feedback=(text,bad=false)=>{ $('control-feedback').textContent=text;$('control-feedback').className='control-feedback'+(bad?' negative':'');};
async function operation(button,action){if(!unlocked){feedback('请先到「合约账户与持仓」使用本机管理密码解锁。',true);return;}if(busyOperations.has(button))return;busyOperations.add(button);button.disabled=true;try{await action();}catch(e){feedback(e.message,true);}finally{busyOperations.delete(button);button.disabled=!unlocked;}}
document.querySelectorAll('[data-pane]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-pane]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));document.querySelectorAll('.control-pane').forEach(p=>p.hidden=p.id!==button.dataset.pane);});
$('market-settings').oninput=()=>{settingsDraft=true;feedback('设置尚未应用，点击「应用设置」使后台生效。');};
$('market-settings').onsubmit=e=>{e.preventDefault();operation(e.submitter,async()=>{await accountRequest('/market-control',{symbol:$('setting-symbol').value,source:$('setting-source').value,interval:Number($('setting-interval').value)});settingsDraft=false;appliedRevision=-1;feedback('设置已保存，采集器将在当前请求结束后应用；下方行情标题显示实际数据来源。');});};
$('market-pause').onclick=e=>operation(e.currentTarget,async()=>{const pause=!lastStatus?.settings.paused;await accountRequest('/market-control',{paused:pause});feedback(pause?'已提交暂停；当前在途请求结束后停止采集。':'已恢复采集，正在等待新行情。');});
$('market-refresh').onclick=e=>operation(e.currentTarget,async()=>{await accountRequest('/market-control',{refresh:true});feedback('已通知后台立即采集，收到新数据后更新时间会变化。');});
$('diagnose').onclick=e=>operation(e.currentTarget,async()=>{$('diagnostic-result').textContent='正在检测两个公共接口…';const result=await accountRequest('/diagnostics',{});$('diagnostic-result').innerHTML=`<p>检测时间：${date(result.at)}</p>`+result.results.map(r=>`<p><strong class="${r.ok?'positive':'negative'}">${r.ok?'✓':'!'} ${escapeText(r.name)}</strong> · ${r.latency_ms} ms<br>${escapeText(r.message)}</p>`).join('');feedback('连接诊断已完成；未发送任何账户密钥。');});
function showAnalysis(a){if(!a)return;$('analysis-output').innerHTML=`<h3>最近一次行情分析 · ${escapeText(a.symbol)}</h3><p class="muted">${date(a.at)} · ${a.count} 根已收盘 K 线 · 数据截止 ${date(a.to_ms/1000)}<br>来源 ${escapeText(a.source)}</p><div class="account-metrics"><article><span>区间涨跌</span><strong>${number(a.return_pct)}%</strong></article><article><span>区间最高</span><strong>${number(a.high)}</strong></article><article><span>区间最低</span><strong>${number(a.low)}</strong></article><article><span>20 根收盘均值</span><strong>${number(a.sma20)}</strong></article></div><p class="muted">${escapeText(a.note)}</p>`;}
async function loadWorkspace(){const w=await accountRequest('/workspace');$('ai-config-status').textContent=w.ai.error||(w.ai.configured?`已保存 · 模型 ${w.ai.model} · 月预算 ¥${w.ai.budget_cny} · ${w.ai.validation?.message||'尚未验证'}`:'未配置 AI API');if(w.ai.configured){$('ai-model').value=w.ai.model||'';$('ai-budget').value=w.ai.budget_cny||30;}$('module-actions').innerHTML=Object.entries(w.modules).map(([id,m])=>`<article><h3>${escapeText(m.title)}</h3><span class="badge ${m.ready?'':'neutral'}">${m.ready?'可手动运行':'尚未满足启动条件'}</span><p>${m.ready?escapeText(m.description||'对已采集的 K 线做描述统计，不调用 AI、不产生订单。'):escapeText(m.blockers[0])}</p><div class="action-row"><button data-module="${id}" data-action="start">${id==='analysis'?'开始数据分析':id==='live'?'实盘授权与启动':id==='simulation'?'开始模拟交易':id==='training'?'开始模型训练':'开始 AI 研究（≤¥0.50）'}</button><button data-module="${id}" data-action="stop">停止</button></div></article>`).join('');showAnalysis(w.analysis);workspaceLoaded=true;}
$('module-actions').onclick=e=>{const b=e.target;if(!b.dataset.module)return;operation(b,async()=>{try{const r=await accountRequest('/module-action',{module:b.dataset.module,action:b.dataset.action});$('module-result').textContent=r.message;showAnalysis(r.analysis);feedback(r.message);}catch(err){$('module-result').textContent=err.message;feedback('启动条件未满足，未启动任何交易或 AI 任务。',true);}});};
$('ai-config-form').onsubmit=e=>{e.preventDefault();operation(e.submitter,async()=>{await accountRequest('/ai-config',{key:$('ai-key').value.trim(),model:$('ai-model').value.trim(),budget_cny:Number($('ai-budget').value)});$('ai-key').value='';await loadWorkspace();feedback('AI 配置已加密保存，请点击验证连接；不会自动启动付费研究。');});};
$('delete-ai').onclick=e=>operation(e.currentTarget,async()=>{await accountRequest('/ai-delete',{});$('ai-key').value='';$('ai-model').value='';await loadWorkspace();feedback('已清除本机 AI 配置。');});
const filterEvents=()=>{if(!lastStatus)return;const term=$('event-search').value.toLowerCase(),level=$('event-level').value;const rows=lastStatus.events.filter(e=>(!level||e.level===level)&&`${e.message} ${e.source}`.toLowerCase().includes(term));$('event-count').textContent=`${rows.length} / ${lastStatus.events.length} 条`;$('events').innerHTML=rows.map(e=>`<div class="event"><time>${date(e.at)}</time><span class="${e.level==='warning'?'badge warning':'muted'}">${e.level==='warning'?'告警':'信息'}</span><span class="message">${escapeText(e.message)}</span></div>`).join('')||'<p class="muted">没有匹配的记录</p>';return rows;};
$('event-search').oninput=filterEvents;$('event-level').onchange=filterEvents;
$('export-events').onclick=()=>{const rows=filterEvents()||[];const csv='\uFEFF时间,来源,级别,内容\n'+rows.map(e=>[date(e.at),e.source,e.level,e.message].map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='系统运行记录.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('chart-zoom-in').onclick=()=>{windowSize=Math.max(5,windowSize-5);renderChart();};$('chart-zoom-out').onclick=()=>{windowSize=Math.min(120,windowSize+5);renderChart();};$('chart-back').onclick=()=>{chartOffset=Math.min(120-windowSize,chartOffset+5);renderChart();};$('chart-live').onclick=()=>{chartOffset=0;windowSize=15;renderChart();};
window.addEventListener('lab-status',()=>{const s=lastStatus.settings;if(!settingsDraft&&s.revision!==appliedRevision){$('setting-symbol').value=s.symbol;$('setting-source').value=s.source;$('setting-interval').value=String(s.interval);appliedRevision=s.revision;}$('market-pause').textContent=s.paused?'恢复采集':'暂停采集';$('collector-state').textContent=`已保存：${s.symbol} · ${s.interval} 秒 · ${s.paused?'暂停':'启用'}（实际状态见服务心跳）`;$('market-refresh').disabled=!unlocked||s.paused;filterEvents();});
setInterval(()=>{document.querySelectorAll('[data-admin]').forEach(b=>b.disabled=!unlocked||busyOperations.has(b)||(b.id==='market-refresh'&&lastStatus?.settings.paused));$('control-lock').textContent=unlocked?'管理面板已解锁':'先解锁管理面板';if(unlocked&&!workspaceLoaded){workspaceLoaded=true;loadWorkspace().catch(e=>{workspaceLoaded=false;feedback(e.message,true);});}if(!unlocked&&workspaceLoaded){workspaceLoaded=false;$('ai-key').value='';$('ai-model').value='';$('ai-config-status').textContent='解锁后查看配置状态';$('analysis-output').innerHTML='';$('module-actions').innerHTML='<p class="muted">请先解锁管理面板，再操作数据分析、AI 研究、模型训练、模拟交易和实盘入口。</p>';}},1000);
